  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public boolean shouldOverrideUrlLoading(WebView v,String u){return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){String u=r.getUrl().toString();if(!u.startsWith("file:///android_asset/"))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));return null;}@Override public void onPageFinished(WebView v,String u){if(u.startsWith("file:///android_asset/"))js("voiceSessionChanged",voiceSessionActive()?"true":"false");}});
  web.addJavascriptInterface(new Bridge(),"Android");web.loadUrl("file:///android_asset/index.html");registerVoiceReceiver();speech=new TextToSpeech(this,status->{if(!dead&&speech!=null&&status==TextToSpeech.SUCCESS){int lang=speech.setLanguage(new Locale("ar"));ready=lang>=0;}});
