  @JavascriptInterface public String newId(){return UUID.randomUUID().toString();}
  private boolean selectVoice(String name){if(speech==null)return false;if(name==null||name.isEmpty()){ready=speech.setLanguage(new Locale("ar"))>=0;if(ready)prefs.edit().remove("tts_voice").commit();return ready;}if(speech.getVoices()==null)return false;for(Voice v:speech.getVoices())if(v.getName().equals(name)&&"ar".equals(v.getLocale().getLanguage())){speech.setVoice(v);prefs.edit().putString("tts_voice",name).commit();ready=true;return true;}return false;}
  private void requestStatus(String endpoint){requestStatus(endpoint,null);}
  private void requestStatus(String endpoint,String query){new Thread(()->{JSONObject payload=new JSONObject();try{if(query!=null)payload.put("query",query);String value=post(endpoint,payload);JSONObject answer=new JSONObject(value);if(query!=null)js("searchReply",answer.toString());else js("capabilitiesReply",answer.toString());}catch(Exception ex){JSONObject err=new JSONObject();try{String reason=ex.getMessage();err.put("error",reason==null||reason.isEmpty()?"تعذر الاتصال بالخادم؛ تحقق من الشبكة وإعداد الرابط":reason);}catch(Exception ignored){}String out=err.toString();js(query==null?"capabilitiesReply":"searchReply",out);}} ,"ram-"+endpoint).start();}
  @JavascriptInterface public void setServer(String u){try{URL v=new URL(u);if(v.getProtocol().equals("https")&&v.getUserInfo()==null&&v.getQuery()==null&&v.getRef()==null)prefs.edit().putString("server",u.replaceAll("/+$","")).apply();}catch(Exception e){message("رابط الخادم غير صالح");}}
  @JavascriptInterface public void openUrl(String u){runOnUiThread(()->{try{Uri uri=Uri.parse(u);if(!"https".equals(uri.getScheme())&&!"http".equals(uri.getScheme()))return;startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception e){message("تعذر فتح الرابط");}});}
  @JavascriptInterface public void chat(String data){runOnUiThread(()->send(data));}
  @JavascriptInterface public void speak(String text){runOnUiThread(()->{stopCloudPlayback();if(ready){String selected=prefs.getString("tts_voice","");if(!selected.isEmpty())selectVoice(selected);float rate="low".equals(prefs.getString("voice_pitch","normal"))?.9f:"high".equals(prefs.getString("voice_pitch","normal"))?1.1f:1f;speech.setSpeechRate(rate);if(Build.VERSION.SDK_INT>=21){speech.setOnUtteranceProgressListener(new android.speech.tts.UtteranceProgressListener(){@Override public void onStart(String id){}@Override public void onDone(String id){if("ram-voice-session".equals(id))resumeVoiceRecognition();}@Override public void onError(String id){if("ram-voice-session".equals(id))resumeVoiceRecognition();}});}speech.speak(text.substring(0,Math.min(text.length(),TextToSpeech.getMaxSpeechInputLength())),TextToSpeech.QUEUE_FLUSH,null,voiceSessionActive()?"ram-voice-session":"ram");}else{message("ثبّت صوتًا عربيًا في إعدادات تحويل النص إلى كلام");resumeVoiceRecognition();}});}
  @JavascriptInterface public void speakCloud(String text){if(text==null||text.trim().isEmpty())return;String value=text.trim().substring(0,Math.min(text.trim().length(),1200));new Thread(()->{File audio=null;try{if(speech!=null)speech.stop();JSONObject body=new JSONObject();body.put("text",value);byte[] bytes=postAudio("tts",body);audio=File.createTempFile("ram-voice-",".mp3",getCacheDir());try(FileOutputStream out=new FileOutputStream(audio)){out.write(bytes);}File readyFile=audio;runOnUiThread(()->playCloudAudio(readyFile));}catch(Exception e){if(audio!=null)audio.delete();String why=e.getMessage()==null?"تعذر طلب صوت ElevenLabs":e.getMessage();message(why);resumeVoiceRecognition();}} ,"ram-elevenlabs").start();}
  @JavascriptInterface public void stopVoice(){runOnUiThread(()->{if(speech!=null)speech.stop();stopCloudPlayback();HttpURLConnection c=ttsRequest;if(c!=null)c.disconnect();});}
  @JavascriptInterface public void startVoiceSession(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},VOICE_PERMISSION);return;}startVoiceService();});}
