  @JavascriptInterface public void exportJobFile(String name,String content){String file=String.valueOf(name==null?"":name).replaceAll("[\\\\/:*?\"<>|]","_").trim();String data=String.valueOf(content==null?"":content);if(file.isEmpty()||data.isEmpty()||data.length()>100000){message("اسم الملف أو محتواه غير صالح أو أكبر من الحد");return;}runOnUiThread(()->{prefs.edit().putString("job_export_name",file).putString("job_export_content",data).apply();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/markdown");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,file);try{startActivityForResult(i,JOB_EXPORT);}catch(Exception e){prefs.edit().remove("job_export_name").remove("job_export_content").apply();message("تعذر فتح اختيار مكان حفظ المخرج");}});}   @JavascriptInterface public void exportData(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"RAM-business-backup.json");try{startActivityForResult(i,EXPORT);}catch(Exception e){message("تعذر فتح اختيار مكان الحفظ");}});}
